UPDATE `oc_product_description` SET `diameter` = 'Name: Pure Copper Water Filter <br>\nSize: Large<br>\nProduct Net Weight: 3900-4400 gm, 8.60-9.70 pound (app) <br>\nProduct Net Height: 54 to 57 cm, 21.26-22.44 inch (app) <br>\nProduct Net Diameter: 25-28 cm, 9.84-11.02 inch (app)<br>\nCapacity Approximate: 22 Liters (10 liters on upper container, 12 liters on lower container)  <br>\nColor: Copper <br>\nUseses Metal: Copper<br><br>\n<p><b>Note:</b> This is manually made by hand according to traditional and intuitive knowledge which mean that size, Product Net Height, weight, and finishing of each next filter can be slightly different than other and may not be same finishing as industrial manufacture.</p>\n\n<p></b>Suggestion:</b> It is suggested to order Extra Candle for your Further need as shipping will cost nearly nothing while order together with filter comparing to single candle order.</p>\n\n<p><b>Cleaning information:</b> According quality of water and its mineral strength, it is suggested to clean filter and candles often with fresh lemon (there are also other products to clean copper utensils but lemon is best and natural) as per your requirement and feelings or when water is dropping slower than in beginning.</p>' WHERE `product_id` = 2299 AND `language_id` = 1;
