UPDATE `oc_product_description` SET `diameter` = 'Name: Pure Copper Water Filter <br>\nSize: Medium<br>\nProduct Net Weight: 3400-3800 gm, 7.50-8.4 pound (app) <br>\nProduct Net Height: 47 to 52 cm, 18.50-20.47 inch (app) <br>\nProduct Net Diameter: 23-25 cm, 9.05-9.84 inch (app)<br>\nCapacity Approximate: 18 Liters (9 liters on upper container, 10 liters on lower container)  <br>\nColor: Copper <br>\nUseses Metal: Copper <br><br>\n<p><b>Note:</b> This is manually made by hand according to traditional and intuitive knowledge which mean that size, Product Net Height, weight, and finishing of each next filter can be slightly different than other and may not be same finishing as industrial manufacture.</p>\n\n<p></b>Suggestion:</b> It is suggested to order Extra Candle for your Further need as shipping will cost nearly nothing while order together with filter comparing to single candle order.</p>\n\n<p><b>Cleaning information:</b> According quality of water and its mineral strength, it is suggested to clean filter and candles often with fresh lemon (there are also other products to clean copper utensils but lemon is best and natural) as per your requirement and feelings or when water is dropping slower than in beginning.</p>' WHERE `product_id` = 2298 AND `language_id` = 1;
