UPDATE `oc_product_description` SET `diameter` = '&lt;p&gt;&lt;span style=&quot;font-size: 13px;&quot;&gt;Nom : 74 MANTRAS dans un boîtier de haut-parleur portable multifunctional avec plusieurs options d\'éclairage, FM, Bluetooth, port USB, mode carte Micro SD, RARE COMBO MANTRA PACKAGE&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-size: 13px;&quot;&gt;Dimensions du haut-parleur : 114*114*131 mm&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-size: 13px;&quot;&gt;Poids du haut-parleur : 523 g. (sauf poids de l\'emballage)&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-size: 13px;&quot;&gt;Note : &quot;Présentation du précieux et précieux forfait Akhanda Mantra Sadhana, conçu pour toucher plus de personnes à un prix abordable. Bénéficiez de notre offre spéciale d\'ouverture de 13 % pour les 54 premiers participants. Obtenez le forfait complet, y compris une caisse de résonance, pour seulement 65 euros. après remise.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-size: 13px;&quot;&gt;&lt;b&gt;Pour ceux qui optent pour la version téléchargeable sans la boîte, (Playlists de Mantras 2 titres, livre en version PDF de 59 pages de ces mantras), elle est disponible pour 45 euros.&quot;&lt;br&gt;&lt;br&gt;&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-size: 13px;&quot;&gt;&lt;b&gt;REMARQUE : Répandre des choses bonnes et positives est considéré comme le plus grand Sewa/Service. Si vous souhaitez participer à ce SEWA (Service) et vendre ces Forfaits Mantra de plus de 10 pièces, il nous fera plaisir de vous proposer des prix discount de gros. Veuillez nous écrire à sales.magicalsb@gmail.com.&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;' WHERE `product_id` = 3658 AND `language_id` = 2;
